"""生成 HDMI-A 菜单专用 32×32 字库，不改 HDMI-B 的 OSD 字库。"""
from pathlib import Path
import argparse
from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parents[1]
CHARSET = '图片波形时间标周期外设蜂鸣器按键板载灯屏幕亮度对比色温恢复默认题'
EXTRA = '字内容速'
FONT = Path('C:/Windows/Fonts/simhei.ttf')


def generate():
    if len(CHARSET) != 32 or len(set(CHARSET)) != 32:
        raise ValueError('菜单基础字库必须保持32个唯一字符；扩展字索引32..35不变')
    font = ImageFont.truetype(str(FONT), 30)
    lines = [
        '// Generated by scripts/gen_monitor_cjk.py; 32 base glyphs, extras 32..35.',
        '// Native 32x32, 1bpp. Registered read: one pixel clock, MSB is leftmost.',
        'module monitor_cjk_rom(',
        '    input  wire        I_clk,',
        '    input  wire [5:0]  I_index,',
        '    input  wire [4:0]  I_row,',
        '    output wire [31:0] O_bits',
        ');',
        '    reg [31:0] glyph_rom [0:1023];',
        '    reg [31:0] extra_rom [0:127];',
        '    reg [31:0] base_bits, extra_bits;',
        '    reg extra_selected;',
        '    integer init_index;',
        '    initial begin',
        '        for (init_index = 0; init_index < 1024; init_index = init_index + 1)',
        "            glyph_rom[init_index] = 32'h00000000;",
        '        for (init_index = 0; init_index < 128; init_index = init_index + 1)',
        "            extra_rom[init_index] = 32'h00000000;",
    ]
    for idx, ch in enumerate(CHARSET + EXTRA):
        img = Image.new('L', (32, 32), 0)
        draw = ImageDraw.Draw(img)
        left, top, right, bottom = draw.textbbox((0, 0), ch, font=font)
        draw.text(((32-right+left)//2-left, (32-bottom+top)//2-top), ch, fill=255, font=font)
        rows = [sum((1 << (31-x)) for x in range(32) if img.getpixel((x,y)) > 100) for y in range(32)]
        if not any(rows):
            raise ValueError(f'空字形: {ch}')
        lines.append('        // ' + ch)
        memory='glyph_rom' if idx<32 else 'extra_rom'
        offset=idx*32 if idx<32 else (idx-32)*32
        for y in range(0,32,4):
            lines.append('        ' + ' '.join(f"{memory}[{offset+y+k}]=32'h{rows[y+k]:08X};" for k in range(4)))
    lines += ['    end', '    always @(posedge I_clk) begin',
              '        base_bits <= glyph_rom[{I_index[4:0], I_row}];',
              '        extra_bits <= extra_rom[{I_index[1:0], I_row}];',
              '        extra_selected <= I_index[5];', '    end',
              '    assign O_bits = extra_selected ? extra_bits : base_bits;', 'endmodule', '']
    return '\n'.join(lines)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='只验证已提交RTL可重现，不写文件')
    args = parser.parse_args()
    target = ROOT/'rtl/video/monitor_cjk_rom.v'
    content = generate()
    if args.check:
        if target.read_bytes() != content.encode('utf-8'):
            raise RuntimeError('32x32菜单字库与生成结果不同')
        print('MONITOR_CJK PASS 32 base and 4 extra native32 glyphs; unchanged bank sizes')
    else:
        target.write_text(content, encoding='utf-8', newline='\n')
        print('Generated native 32x32 menu glyph ROM')
